const RC=META.parts.length+1, QZ=RC+1, LS=RC+2, OUT=RC+3;

/* ---- drawing helpers for this lesson (prefixed OF_ so nothing clashes with the engine) ---- */
const OF_F='font-family="Nunito Sans, sans-serif"';
const OF_T=(x,y,t,o={})=>`<text x="${(+x).toFixed(1)}" y="${(+y).toFixed(1)}" ${OF_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.ex?' '+o.ex:''}>${t}</text>`;
const OF_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${(+x1).toFixed(1)}" y1="${(+y1).toFixed(1)}" x2="${(+x2).toFixed(1)}" y2="${(+y2).toFixed(1)}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const OF_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.ex?' '+o.ex:''}/>`;
const OF_arrow=(x1,y1,x2,y2,col='#18213A',w=3,ex='')=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return OF_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w,ex)+`<polygon points="${x2.toFixed(1)},${y2.toFixed(1)} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const OF_poly=(pts,col,w=4,ex='')=>`<polyline points="${pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
const OF_GREY='#5C6577', OF_CORE='#DBE4FF', OF_CLAD='#F1F3F5';
const OF_SUB=t=>`<tspan baseline-shift="-0.2em" font-size="72%">${t}</tspan>`;
const OF_SUP=t=>`<tspan baseline-shift="super" font-size="70%">${t}</tspan>`;
/* the book's numbers, computed once */
const OF_AKM=0.2/4.343;                                        // 0.2 dB/km in nepers per km = 0.04605
const OF_LEFF=(1-Math.exp(-OF_AKM*80))/OF_AKM;                 // 21.17 km
const OF_DSTD=l=>17*(l-1310)/240;                              // standard fiber: zero at 1310 nm, +17 at 1550 nm
const OF_DDSF=l=>0.07*(l-1550);                                // dispersion-shifted fiber: zero at 1550 nm
/* residual of 100 km line (S = +0.058) + 20 km DCF (S = -0.10) about 1550 nm, from the worked example in the notes */
const OF_RES=l=>100*(17+0.058*(l-1550))+20*(-85-0.10*(l-1550));   // -76 at 1530, +57 at 1565
/* a Gaussian pulse drawn on a baseline */
const OF_pulse=(cx,by,h,s,col,w=4)=>{const p=[];for(let i=-30;i<=30;i++){const x=cx+i*s/10;p.push([x,by-h*Math.exp(-0.5*(i/10)**2)])}return OF_poly(p,col,w)};
/* a fiber strip drawn side-on */
const OF_strip=(x0,x1,yc,hc)=>`<rect x="${x0}" y="${yc-hc-12}" width="${x1-x0}" height="${2*hc+24}" rx="10" fill="${OF_CLAD}" stroke="#ADB5BD" stroke-width="2"/><rect x="${x0}" y="${yc-hc}" width="${x1-x0}" height="${2*hc}" fill="${OF_CORE}" stroke="${BLU}" stroke-width="2"/>`;
/* the decay e^(-αz) over 80 km at 0.2 dB/km, in a box x0..x1, y for P/P0 = 1 at yt and 0 at yb */
const OF_decay=(x0,x1,yt,yb,col,w=4)=>{const p=[];for(let i=0;i<=80;i++){p.push([x0+(x1-x0)*i/80,yb-(yb-yt)*Math.exp(-OF_AKM*i)])}return OF_poly(p,col,w)};
/* a little WDM spectrum: spikes at xs on baseline by */
const OF_comb=(xs,by,hs,col,w=8)=>xs.map((x,i)=>OF_L(x,by,x,by-(Array.isArray(hs)?hs[i]:hs),col,w)).join('');

